        (string) ($item['discount_percentage'] ?? '0'),
        (string) ($item['expected_delivery_date'] ?? ''),
        (string) ($item['warehouse_key'] ?? ''),
        (string) ($item['rfq_key'] ?? $buyingQuotationInput['rfq_key'] ?? ''),
        (string) ($item['rfq_item_key'] ?? ''),
    ]);
}
$buyingQuotationItemsText = (string) ($buyingQuotationInput['items_text'] ?? implode("\n", $buyingQuotationLines));
$buyingQuotationActionLabels = [
    'submit_buying_supplier_quotation' => 'Submit Quotation',
    'stop_buying_supplier_quotation' => 'Stop Quotation',
    'resume_buying_supplier_quotation' => 'Resume Quotation',
    'expire_buying_supplier_quotation' => 'Expire Quotation',
    'cancel_buying_supplier_quotation' => 'Cancel Quotation',
    'amend_buying_supplier_quotation' => 'Amend Quotation',
];
