 px-3" required><option value="">Select RFQ</option><?php foreach ($buyingQuotationRfqs as $rfq): ?><?php if ((string) $rfq['document_status'] === 'SUBMITTED'): ?><option value="<?= bx_h((string) $rfq['rfq_key']) ?>" <?= (string) ($buyingQuotationMapInput['rfq_key'] ?? '') === (string) $rfq['rfq_key'] ? 'selected' : '' ?>><?= bx_h((string) $rfq['rfq_number']) ?></option><?php endif; ?><?php endforeach; ?></select></label><label class="grid gap-1.5 text-sm"><span class="font-medium">Invited supplier</span><select name="supplier_key" class="h-10 rounded-md border bg-background px-3" required><option value="">Select supplier</option><?php foreach ($buyingQuotationSuppliers as $supplier): ?><?php if ((string) $supplier['supplier_status'] === 'ACTIVE'): ?><option value="<?= bx_h((string) $supplier['supplier_key']) ?>" <?= (string) ($buyingQuotationMapInput['supplier_key'] ?? '') === (string) $supplier['supplier_key'] ? 'selected' : '' ?>><?= bx_h((string) $supplier['supplier_name']) ?></option><?php endif; ?><?php endforeach; ?></select></label></div></div><footer class="m-0 flex w-full shrink-0 items-center justify-end gap-2 rounded-none border-t bg-popover px-6 py-4"><button type="button" data-record-modal-close class="h-9 rounded-md border bg-background px-3 text-sm">Cancel</button><button type="submit" class="h-9 rounded-md bg-primary px-3 text-sm font-medium text-primary-foreground">Prepare Draft</button></footer></form></section></div>

<div id="buying-supplier-quotation-action-modal" data-record-modal <?= $buyingReopenSupplierQuotationLifecycleModal ? 'data-record-modal-open-on-load' : '' ?> hidden class="fixed inset-0 grid place-items-center bg-background/80 p-4 backdrop-blur-sm" style="z-index: 100;" role="dialog" aria-modal="true" aria-labelledby="buying-quotation-action-title" aria-describedby="buying-quotation-action-description"><section class="flex max-h-[calc(100dvh-2rem)] w-[calc(100vw-2rem)] max-w-xl flex-col overflow-hidden rounded-lg border bg-popover shadow-lg" role="document"><header class="flex shrink-0 items-start justify-between gap-4 border-b bg-popover px-6 py-4"><div><h2 id="buying-quotation-action-title" data-buying-quotation-action-title class="text-base font-semibold"><?= bx_h($buyingQuotationActionLabels[$buyingQuotationLifecycleAction]) ?></h2><p id="buying-quotation-action-description" class="mt-1 text-sm text-muted-foreground">Review the locked lifecycle transition before confirmation.</p></div><button type="button" data-record-modal-close class="inline-flex size-8 items-center justify-center rounded-md border bg-background" aria-label="Close quotation action dialog"><span class="material-symbols-rounded text-base" aria-hidden="true">close</span></button></header><form method="post" data-confirm-submit data-confirm-message="Confirm this Supplier Quotation action?" data-buying-quotation-action-form class="contents"><input type="hidden" name="csrf" value="<?= bx_h(bx_csrf_token()) ?>"><input type="hidden" name="module_view" value="buying-procurement"><input type="hidden" name="section" value="supplier-quotations"><input type="hidden" name="action" value="<?= bx_h($buyingQuotationLifecycleAction) ?>"><input type="hidden" name="supplier_quotation_key" value="<?= bx_h((string) ($buyingQuotationLifecycleInput['supplier_quotation_key'] ?? '')) ?>"><input type="hidden" name="expected_version" value="<?= bx_h((string) ($buyingQuotationLifecycleInput['expected_version'] ?? '')) ?>"><div class="min-h-0 flex-1 overflow-y-auto p-6"><?php if ($buyingReopenSupplierQuotationLifecycleModal): ?><div class="mb-4 rounded-md bg-destructive/10 px-3 py-2 text-sm text-destructive" role="alert"><?= bx_h($buyingFormError) ?></div><?php endif; ?><p class="text-sm">Apply <strong data-buying-quotation-action-label><?= bx_h($buyingQuotationActionLabels[$buyingQuotationLifecycleAction]) ?></strong> to <span data-buying-quotation-action-record class="font-medium"><?= bx_h((string) ($buyingQuotationLifecycleInput['quotation_number'] ?? 'this quotation')) ?></span>?</p><label class="mt-4 grid gap-1.5 text-sm"><span class="font-medium">Effective date</span><input type="date" name="as_of" value="<?= bx_h((string) ($buyingQuotationLifecycleInput['as_of'] ?? date('Y-m-d'))) ?>" class="h-10 rounded-md border bg-background px-3"></label></div><footer class="m-0 flex w-full shrink-0 items-center justify-end gap-2 rounded-none border-t bg-popover px-6 py-4"><button type="button" data-record-modal-close class="h-9 rounded-md border bg-background px-3 text-sm">Cancel</button><button type="submit" data-buying-quotation-action-submit class="h-9 rounded-md bg-primary px-3 text-sm font-medium text-primary-foreground"><?= bx_h($buyingQuotationActionLabels[$buyingQuotationLifecycleAction]) ?></button></footer></form></section></div>

<script>
(() => {
    const form = document.querySelector('[data-buying-supplier-quotation-form]');
    const title = document.querySelector('#buying-supplier-quotation-title');
    document.querySelectorAll('[data-buying-supplier-quotation-open]').forEach((button) => button.addEventListener('click', () => {
        if (!form || button.hasAttribute('data-buying-supplier-quotation-edit')) return;
        form.reset(); form.elements.supplier_quotation_key.value = ''; form.elements.expected_version.value = ''; form.elements.transaction_date.value = <?= json_encode(date('Y-m-d')) ?>;
        if (title) title.textContent = 'New Supplier Quotation';
    }));
    document.querySelectorAll('[data-buying-supplier-quotation-edit]').forEach((button) => button.addEventListener('click', () => {
        if (!form) return; const record = JSON.parse(button.dataset.quotationPayload || '{}'); Object.entries(record).forEach(([key, value]) => { const control = form.elements.namedItem(key); if (control) control.value = value ?? ''; }); if (title) title.textContent = 'Edit Supplier Quotation';
    }));
    const labels = <?= json_encode($buyingQuotationActionLabels, JSON_UNESCAPED_SLASHES | JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT) ?>;
    const actionForm = document.querySelector('[data-buying-quotation-action-form]');
    document.querySelectorAll('[data-buying-quotation-action]').forEach((button) => button.addEventListener('click', () => {
        if (!actionForm) return; const action = button.dataset.buyingQuotationAction || ''; actionForm.elements.action.value = action; actionForm.elements.supplier_quotation_key.value = button.dataset.quotationKey || ''; actionForm.elements.expected_version.value = button.dataset.quotationVersion || ''; const label = labels[action] || 'Apply Quotation Action'; document.querySelectorAll('[data-buying-quotation-action-title], [data-buying-quotation-action-label], [data-buying-quotation-action-submit]').forEach((node) => { node.textContent = label; }); const record = document.querySelector('[data-buying-quotation-action-record]'); if (record) record.textContent = button.dataset.quotationNumber || 'this quotation';
    }));
})();
</script>
